package com.braseiro.dnd5e;

import org.json.JSONArray;
import org.json.JSONObject;
import java.util.Locale;

/** Xanathar chapter 2 master tools: tool synergy, encounter construction and trap profiles. No automatic rolls. */
public final class XanatharMasterToolsRulesEngine {
    public static final String BOOK="Xanathar's Guide to Everything";
    private XanatharMasterToolsRulesEngine(){}
    public static JSONObject descriptor(){JSONObject o=new JSONObject();try{o.put("id","xanathar_master_tools").put("book",BOOK).put("status","compiled_phase_1").put("auto_rolls",false).put("procedures",new JSONArray().put("xanathar.tools.synergy").put("xanathar.encounter.solo_cr").put("xanathar.trap.profile").put("xanathar.trap.complex"));}catch(Exception ignored){}return o;}
    public static JSONObject execute(String id,JSONObject in){JSONObject x=in==null?new JSONObject():in;if("xanathar.tools.synergy".equals(id))return toolSynergy(x);if("xanathar.encounter.solo_cr".equals(id))return soloCr(x);if("xanathar.trap.profile".equals(id))return trapProfile(x);if("xanathar.trap.complex".equals(id))return complexTrap(x);return blocked("unknown_xanathar_master_tool_rule");}

    private static JSONObject toolSynergy(JSONObject in){JSONObject o=base(78);try{boolean tool=in.optBoolean("tool_proficient",false),skill=in.optBoolean("skill_proficient",false),bothApply=in.optBoolean("both_apply_to_same_check",false);boolean advantage=tool&&skill&&bothApply;return o.put("advantage_recommended",advantage).put("additional_success_benefit_recommended",advantage).put("no_double_proficiency_bonus",true).put("tool_special_use_available",tool);}catch(Exception e){return blocked(o,"invalid_inputs");}}

    private static JSONObject soloCr(JSONObject in){JSONObject o=base(88);try{int level=in.optInt("character_level",0),party=in.optInt("party_size",0);if(level<1||level>20)return blocked(o,"character_level_1_to_20_required");if(party<4||party>6)return blocked(o,"solo_table_supports_party_size_4_to_6");int[][] cr={{2,2,1},{4,3,2},{5,4,3},{6,5,4},{9,8,7},{10,9,8},{11,10,9},{12,11,10},{13,12,11},{14,13,12},{15,14,13},{17,16,15},{18,17,16},{19,18,17},{20,19,18},{21,20,19},{22,21,20},{22,21,20},{23,22,21},{24,23,22}};int idx=party==6?0:(party==5?1:2);int optimal=cr[level-1][idx];String difficulty=norm(in.optString("difficulty","standard"));o.put("party_size",party).put("character_level",level).put("standard_solo_cr",optimal).put("legendary_creature_recommended",true).put("difficulty",difficulty).put("warning","Also compare monster damage, PC maximum HP, saves and party damage; CR does not tell the whole story.");if(any(difficulty,"standard","padrao","padrão")||difficulty.isEmpty())o.put("recommended_solo_cr",optimal);else if(any(difficulty,"easy","facil"))o.put("recommended_solo_cr_max",Math.max(0,optimal-3)).put("guidance","For an easier solo encounter, use a legendary creature whose CR is about 3 lower than the standard solo value.");else if(any(difficulty,"deadly","mortal","potentially deadly","potencialmente mortal")){o.put("recommended_solo_cr",JSONObject.NULL).put("requires_resolution",true).put("guidance","For a potentially deadly encounter, treat a four-character party as six when consulting the table. Other party sizes require DM judgment; no invented numeric CR adjustment is applied.");if(party==4)o.put("party_size_for_table",6).put("recommended_solo_cr_for_four_as_six",cr[level-1][0]);}else return blocked(o,"difficulty_standard_easy_or_deadly_required");return o;}catch(Exception e){return blocked(o,"invalid_inputs");}}

    private static JSONObject trapProfile(JSONObject in){JSONObject o=base(116);try{String threat=norm(in.optString("threat"));int level=in.optInt("character_level",0);if(level<1||level>20)return blocked(o,"character_level_1_to_20_required");int idx=any(threat,"moderate","moderado")?0:(any(threat,"dangerous","perigoso")?1:(any(threat,"deadly","mortal")?2:-1));if(idx<0)return blocked(o,"threat_moderate_dangerous_or_deadly_required");int dc=new int[]{10,15,20}[idx],atk=new int[]{5,8,12}[idx];int tier=level<=4?0:(level<=10?1:(level<=16?2:3));String[][] dmg={{"1d10","2d10","4d10"},{"2d10","4d10","10d10"},{"4d10","10d10","18d10"},{"10d10","18d10","24d10"}};return o.put("save_or_check_dc",dc).put("attack_bonus",atk).put("multi_target_damage_d10",dmg[tier][idx]).put("single_target_use_d6_instead",true).put("tier",tierName(tier)).put("threat",threat);}catch(Exception e){return blocked(o,"invalid_inputs");}}

    private static JSONObject complexTrap(JSONObject in){JSONObject o=base(118);try{String speed=norm(in.optString("initiative_speed"));JSONArray initiatives=new JSONArray();if(any(speed,"slow","lenta"))initiatives.put(10);else if(any(speed,"fast","rapida"))initiatives.put(20);else if(any(speed,"very fast","muito rapida","muito rápida"))initiatives.put(20).put(10);else return blocked(o,"initiative_speed_slow_fast_or_very_fast_required");int level=in.optInt("character_level",0);if(level<1||level>20)return blocked(o,"character_level_1_to_20_required");int xp=level<=4?650:(level<=10?3850:(level<=16?11000:21500));int successes=Math.max(1,in.optInt("successful_countermeasures_required",3));return o.put("initiative_counts",initiatives).put("acts_after_creatures_on_same_initiative",true).put("default_successful_countermeasures_required",successes).put("active_dynamic_constant_elements_supported",true).put("xp_if_neutralized_or_survived",xp);}catch(Exception e){return blocked(o,"invalid_inputs");}}

    private static JSONObject base(int page){JSONObject o=new JSONObject();try{o.put("book",BOOK).put("page",page).put("status","ok").put("auto_rolls",false);}catch(Exception ignored){}return o;}private static JSONObject blocked(String r){return blocked(base(0),r);}private static JSONObject blocked(JSONObject o,String r){try{o.put("status","blocked").put("requires_resolution",true).put("reason",r);}catch(Exception ignored){}return o;}
    private static String norm(String s){return s==null?"":java.text.Normalizer.normalize(s.toLowerCase(new Locale("pt","BR")),java.text.Normalizer.Form.NFD).replaceAll("\\p{M}+","").trim();}private static boolean any(String s,String... xs){for(String x:xs)if(s.equals(norm(x)))return true;return false;}private static String tierName(int t){return new String[]{"1-4","5-10","11-16","17-20"}[t];}
}
